package org.tstrans;

/**
 * Thrown when typed-KLV decode rejects input. {@link Kind} mirrors the
 * decode-error classification in {@code tst_core::error::KlvDecodeError}.
 */
public final class KlvDecodeException extends BindingException {
    private static final long serialVersionUID = 1L;

    /**
     * Discriminant; values map 1:1 from the Rust {@code KlvDecodeError} variants.
     *
     * <p>Persist {@link #name()}, never {@link #ordinal()}: the declaration order is not part of the API.
     */
    public enum Kind {
        // BEGIN GENERATED by print-kinds from crates/tst-pipeline/src/binding/kind.rs; do not edit
        /** Unexpected universal label. */
        BAD_UNIVERSAL_LABEL,
        /** KLV set truncated, or a BER length malformed or overflowing. */
        TRUNCATED_SET,
        /** ST 0601 checksum or ST 0806 CRC-32 mismatch. */
        CHECKSUM_MISMATCH,
        /** Duplicate tag in a set. */
        DUPLICATE_TAG,
        /** A spec-mandatory tag is missing or misplaced. */
        MISSING_REQUIRED_TAG,
        /**
         * Any other structural KLV decode failure (malformed tag, non-canonical
         * BER, trailing bytes, field validation).
         */
        MALFORMED_BYTES,
        /**
         * Library-internal failure: an invariant tripped that should not occur in
         * well-formed use (file an issue with reproduction bytes), or a poisoned
         * handle lock.
         */
        INTERNAL,
        // END GENERATED by print-kinds
    }

    private final Kind kind;

    public KlvDecodeException(Kind kind, String message) {
        super(message);
        this.kind = kind;
    }

    /** @return the error discriminant. */
    public Kind kind() {
        return kind;
    }
}
